#define main legacy_main
#include "../wyllie-cuda/main.cu"
#undef main
#include <cstdint>
#include <cstring>
#include <string>
struct Fixture{int n;bool random;std::vector<int>next;std::vector<long>input,rank,packed,got;long*device;Fixture(int size,bool rnd):n(size),random(rnd),next(n),input(n),rank(n),packed(n),got(n){if(random)random_list(next);else ordered_list(next);int node=0,tail=-1;std::vector<bool>seen(n,false);for(int r=n-1;r>=0;r--){if(node<0||node>=n||seen[node])abort();seen[node]=true;rank[node]=r;tail=node;node=next[node];}if(node!=NIL)abort();for(int i=0;i<n;i++){uint64_t bits=(uint64_t(uint32_t(next[i]))<<32)|uint32_t(next[i]==NIL?0:1);memcpy(&input[i],&bits,8);bits=(uint64_t(uint32_t(i==tail?NIL:tail))<<32)|uint32_t(rank[i]);memcpy(&packed[i],&bits,8);}cudaMalloc(&device,n*8);}void launch(){wyllie<<<(n+255)/256,256>>>(device,n);}void reset(){cudaMemcpy(device,input.data(),n*8,cudaMemcpyHostToDevice);}};
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):5;std::vector<Fixture>fs;std::vector<long>prefix;for(int n:{513,1027})for(bool rnd:{false,true}){fs.emplace_back(n,rnd);auto&f=fs.back();prefix.push_back(n);prefix.push_back(rnd);for(int v:f.next)prefix.push_back(v);prefix.insert(prefix.end(),f.input.begin(),f.input.end());f.reset();f.launch();}cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){double elapsed=0;for(int z=0;z<rep;z++)for(auto&f:fs){f.reset();cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();f.launch();cudaDeviceSynchronize();elapsed+=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep;}bool ok=cudaGetLastError()==cudaSuccess;std::vector<long>got;for(auto&f:fs){cudaMemcpy(f.got.data(),f.device,f.n*8,cudaMemcpyDeviceToHost);ok&=f.got==f.packed;got.insert(got.end(),f.got.begin(),f.got.end());for(int i=0;i<f.n;i++){long rank=f.got[i]&MASK;ok&=rank==f.rank[i];got.push_back(rank);}}auto art=prefix;art.insert(art.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(art.data(),8,art.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":0.0,\"max_rel_error\":0.0,\"timing_region\":\"sum_four_inplace_list_rank_kernels_eachresetexcluded\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"int64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",got.size(),rep,path.c_str(),art.size());if(!ok)return 2;}for(auto&f:fs)cudaFree(f.device);}
